                                _DetailItem(
                                  label: l10n.txSubType,
                                  detail: _transaction.subType.toString(),
                                ),

                              isDesktop
                                  ? const _Divider()
                                  : const SizedBox(height: 12),
                              _TxidDetailItem(
                                coin: coin,
                                txid: _transaction.txid,
